33	/**
34	 * Simple JavaBean domain object representing an owner.
35	 *
36	 * @author Ken Krebs
37	 * @author Juergen Hoeller
38	 * @author Sam Brannen
39	 * @author Michael Isvy
40	 */
41	@Entity
42	@Table(name = "owners")
43	public class Owner extends Person {
44	    @Column(name = "title")
45	    private String title;
46	
47	    @Column(name = "address")
48	    private String address;
49	
50	    @Column(name = "address_line1")
51	    private String addressLine1;
52	
53	    @Column(name = "address_line2")
54	    private String addressLine2;
55	
56	    @Column(name = "city")
57	    @NotEmpty
58	    private String city;
59	
60	    @Column(name = "postcode")
61	    private String postcode;
62	
63	    @Column(name = "telephone")
64	    @NotEmpty
65	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
66	    private String telephone;
67	
68	    @Column(name = "email")
69	    @Email
70	    private String email;
71	
72	    @Column(name = "registration_date", columnDefinition = "DATE")
73	    private LocalDate registrationDate;
74	
75	    @Column(name = "birth_date", columnDefinition = "DATE")
76	    private LocalDate birthDate;
77	
78	    @Column(name = "member_id")
79	    private String memberId;
80	
81	    @Column(name = "household_id")
82	    private String householdId;
83	
84	    @Column(name = "namesake_count")
85	    private Integer namesakeCount;
86	
87	    @Column(name = "bulk_signup_warning")
88	    private boolean bulkSignupWarning;
89	
90	    @Column(name = "capacity_warning")
91	    private boolean capacityWarning;
92	
93	    @Column(name = "household_member_count")
94	    private Integer householdMemberCount;
95	
96	    @Column(name = "membership_level_cap")
97	    private Integer membershipLevelCap;
98	
99	    @Column(name = "possible_duplicate")
100	    private boolean possibleDuplicate;
101	
102	    @Column(name = "possible_duplicate_of")
103	    private Integer possibleDuplicateOf;
104	
105	    @Column(name = "deleted")
106	    private boolean deleted;
107	
108	    @Column(name = "idempotency_key")
109	    private String idempotencyKey;
110	
111	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
112	    private Set<Pet> pets;
113	
114	    public String getTitle() {
115	        return this.title;
116	    }
117	
118	    public void setTitle(String title) {
119	        this.title = title;
120	    }
121	
122	    /**
123	     * Derive the owner's read-only {@code salutation}: the honorific {@code title} and
124	     * {@code lastName} joined by a single space ({@code '<title> <lastName>'}) when a title has
125	     * been supplied, otherwise just the {@code lastName}. A {@code null} or blank title yields the
126	     * bare last name.
127	     */
128	    @Transient
129	    public String getSalutation() {
130	        if (this.title == null || this.title.isBlank()) {
131	            return getLastName();
132	        }
133	        return this.title + " " + getLastName();
134	    }
135	
136	    public String getAddress() {
137	        return this.address;
138	    }
139	
140	    public void setAddress(String address) {
141	        this.address = address;
142	    }
143	
144	    public String getAddressLine1() {
145	        return this.addressLine1;
146	    }
147	
148	    public void setAddressLine1(String addressLine1) {
149	        this.addressLine1 = addressLine1;
150	    }
151	
152	    public String getAddressLine2() {
153	        return this.addressLine2;
154	    }
155	
156	    public void setAddressLine2(String addressLine2) {
157	        this.addressLine2 = addressLine2;
158	    }
159	
160	    public String getCity() {
161	        return this.city;
162	    }
163	
164	    public void setCity(String city) {
165	        this.city = city;
166	    }
167	
168	    public String getPostcode() {
169	        return this.postcode;
170	    }
171	
172	    public void setPostcode(String postcode) {
173	        this.postcode = postcode;
174	    }
175	
176	    public String getTelephone() {
177	        return this.telephone;
178	    }
179	
180	    public void setTelephone(String telephone) {
181	        this.telephone = telephone;
182	    }
183	
184	    public String getEmail() {
185	        return this.email;
186	    }
187	
188	    public void setEmail(String email) {
189	        this.email = email;
190	    }
191	
192	    public LocalDate getRegistrationDate() {
193	        return this.registrationDate;
194	    }
195	
196	    public void setRegistrationDate(LocalDate registrationDate) {
197	        this.registrationDate = registrationDate;
198	    }
199	
200	    public LocalDate getBirthDate() {
201	        return this.birthDate;
202	    }
203	
204	    public void setBirthDate(LocalDate birthDate) {
205	        this.birthDate = birthDate;
206	    }
207	
208	    /**
209	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
210	     * owner's {@code registrationDate} (falling back to the current date when no registration date
211	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
212	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
213	     */
214	    @Transient
215	    public String getAgeBand() {
216	        if (this.birthDate == null) {
217	            return null;
218	        }
219	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
220	        int age = Period.between(this.birthDate, reference).getYears();
221	        if (age < 18) {
222	            return "MINOR";
223	        }
224	        if (age < 65) {
225	            return "ADULT";
226	        }
227	        return "SENIOR";
228	    }
229	
230	    public String getMemberId() {
231	        return this.memberId;
232	    }
233	
234	    public void setMemberId(String memberId) {
235	        this.memberId = memberId;
236	    }
237	
238	    /**
239	     * The leading alphabetic REGION segment of a {@code memberId} formatted
240	     * {@code '<REGION><FY><HASH8><CHK>'} (e.g. {@code 'NSW'} for {@code 'NSW271A2B3C4D5'}), or
241	     * {@code null} when {@code memberId} is {@code null} or does not begin with a letter. REGION is
242	     * always a run of letters immediately followed by the 2-digit fiscal year, so the leading letter
243	     * run is exactly the region code.
244	     */
245	    public static String regionSegment(String memberId) {
246	        if (memberId == null) {
247	            return null;
248	        }
249	        int i = 0;
250	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
251	            i++;
252	        }
253	        return i == 0 ? null : memberId.substring(0, i);
254	    }
255	
256	    /**
257	     * The 2-digit fiscal-year (FY) segment of a {@code memberId} formatted
258	     * {@code '<REGION><FY><HASH8><CHK>'} (e.g. {@code '27'} for {@code 'NSW271A2B3C4D5'}), the two
259	     * digits immediately following the {@link #regionSegment(String) REGION}. Returns {@code null}
260	     * when {@code memberId} has no region prefix or is too short to carry a 2-digit FY.
261	     */
262	    public static String fiscalYearSegment(String memberId) {
263	        String region = regionSegment(memberId);
264	        if (region == null || memberId.length() < region.length() + 2) {
265	            return null;
266	        }
267	        String fy = memberId.substring(region.length(), region.length() + 2);
268	        for (int i = 0; i < fy.length(); i++) {
269	            if (fy.charAt(i) < '0' || fy.charAt(i) > '9') {
270	                return null;
271	            }
272	        }
273	        return fy;
274	    }
275	
276	    public String getHouseholdId() {
277	        return this.householdId;
278	    }
279	
280	    public void setHouseholdId(String householdId) {
281	        this.householdId = householdId;
282	    }
283	
284	    public Integer getNamesakeCount() {
285	        return this.namesakeCount;
286	    }
287	
288	    public void setNamesakeCount(Integer namesakeCount) {
289	        this.namesakeCount = namesakeCount;
290	    }
291	
292	    /**
293	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
294	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
295	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
296	     * the owner's tenure is at least one elapsed fiscal year (measured from the
297	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
298	     */
299	    @Transient
300	    public Integer getMembershipPoints() {
301	        int points = 0;
302	        if (this.email != null && !this.email.isBlank()) {
303	            points += 2;
304	        }
305	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
306	            points += 1;
307	        }
308	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
309	            points += 2;
310	        }
311	        if (hasTenureOverOneFiscalYear()) {
312	            points += 3;
313	        }
314	        return points;
315	    }
316	
317	    /**
318	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
319	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
320	     * points, and level 4 for 6 or more points. The result is then capped at the owner's
321	     * {@code membershipLevelCap} when one has been assigned, so a new household member can never
322	     * exceed one above the highest level already present in their household (see
323	     * {@link #getMembershipLevelCap()}).
324	     */
325	    @Transient
326	    public Integer getMembershipLevel() {
327	        int points = getMembershipPoints();
328	        int level;
329	        if (points <= 1) {
330	            level = 1;
331	        }
332	        else if (points <= 3) {
333	            level = 2;
334	        }
335	        else if (points <= 5) {
336	            level = 3;
337	        }
338	        else {
339	            level = 4;
340	        }
341	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
342	            return this.membershipLevelCap;
343	        }
344	        return level;
345	    }
346	
347	    /**
348	     * The ceiling applied to this owner's derived {@code membershipLevel}: one above the highest
349	     * {@code membershipLevel} among the owner's household members (same last name and postcode) at
350	     * creation time. {@code null} when the owner had no existing household member, in which case no
351	     * cap applies.
352	     */
353	    public Integer getMembershipLevelCap() {
354	        return this.membershipLevelCap;
355	    }
356	
357	    public void setMembershipLevelCap(Integer membershipLevelCap) {
358	        this.membershipLevelCap = membershipLevelCap;
359	    }
360	
361	    /**
362	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
363	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
364	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
365	     * never qualifies.
366	     */
367	    @Transient
368	    private boolean hasTenureOverOneFiscalYear() {
369	        if (this.registrationDate == null) {
370	            return false;
371	        }
372	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
373	    }
374	
375	    /**
376	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the two-digit
377	     * fiscal-year (FY) segment carried by the owner's {@code memberId}
378	     * ({@code '<REGION><FY><HASH8><CHK>'}), so the reported fiscal year and the FY embedded in the
379	     * memberId stay in lock-step. Falls back to computing YY from the last two digits of the fiscal
380	     * year of the owner's business-day-adjusted {@code registrationDate} (the fiscal year starting on
381	     * 1 July, so a registration on or after 1 July belongs to the fiscal year ending the following
382	     * 30 June) when the owner has no {@code memberId} yet. Returns {@code null} when the owner has
383	     * neither a {@code memberId} nor a {@code registrationDate}, so the field is omitted from the
384	     * response.
385	     */
386	    @Transient
387	    public String getFiscalYear() {
388	        String fy = fiscalYearSegment(this.memberId);
389	        if (fy != null) {
390	            return "FY" + fy;
391	        }
392	        if (this.registrationDate == null) {
393	            return null;
394	        }
395	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
396	    }
397	
398	    /**
399	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
400	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
401	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
402	     * current year's fiscal year.
403	     */
404	    public static int fiscalYearOf(LocalDate date) {
405	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
406	    }
407	
408	    /**
409	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners: the
410	     * full lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
411	     * soundex(lastName)}. The telephone and email are already stored in their canonical (E.164 /
412	     * lower-cased) form, so a {@code null} or blank email contributes an empty middle segment, and
413	     * the last name is reduced to its {@link Soundex} code (empty when there is no last name). Two
414	     * owners are duplicates only when their whole {@code identityKey} is equal.
415	     */
416	    @Transient
417	    public String getIdentityKey() {
418	        String telephonePart = this.telephone == null ? "" : this.telephone;
419	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
420	        String soundexPart = Soundex.encode(getLastName());
421	        return Sha256.hex(telephonePart + "|" + emailPart + "|" + soundexPart);
422	    }
423	
424	    public boolean isBulkSignupWarning() {
425	        return this.bulkSignupWarning;
426	    }
427	
428	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
429	        this.bulkSignupWarning = bulkSignupWarning;
430	    }
431	
432	    /**
433	     * Whether this owner was flagged at creation as approaching the per-city capacity limit: its city
434	     * already held between 40 and 49 owners (inclusive) at the moment this owner was created, close to
435	     * the hard limit of 50. The owner is still created; this flag is advisory.
436	     */
437	    public boolean isCapacityWarning() {
438	        return this.capacityWarning;
439	    }
440	
441	    public void setCapacityWarning(boolean capacityWarning) {
442	        this.capacityWarning = capacityWarning;
443	    }
444	
445	    public Integer getHouseholdMemberCount() {
446	        return this.householdMemberCount;
447	    }
448	
449	    public void setHouseholdMemberCount(Integer householdMemberCount) {
450	        this.householdMemberCount = householdMemberCount;
451	    }
452	
453	    /**
454	     * Whether this owner was flagged at creation as a possible (soft) duplicate: its
455	     * {@code identityKey} differs from every existing owner's, but it shares an existing owner's
456	     * {@code soundex(lastName)} and postcode. The owner is still created; this flag is advisory.
457	     */
458	    public boolean isPossibleDuplicate() {
459	        return this.possibleDuplicate;
460	    }
461	
462	    public void setPossibleDuplicate(boolean possibleDuplicate) {
463	        this.possibleDuplicate = possibleDuplicate;
464	    }
465	
466	    /**
467	     * The id of the existing owner this one soft-matched against (same {@code soundex(lastName)} and
468	     * postcode, different {@code identityKey}), or {@code null} when {@link #isPossibleDuplicate()}
469	     * is {@code false}.
470	     */
471	    public Integer getPossibleDuplicateOf() {
472	        return this.possibleDuplicateOf;
473	    }
474	
475	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
476	        this.possibleDuplicateOf = possibleDuplicateOf;
477	    }
478	
479	    /**
480	     * Derive the owner's read-only {@code riskFlag}: {@code true} when any of the owner's risk
481	     * signals is present — the owner is a possible (soft) duplicate ({@link #isPossibleDuplicate()}),
482	     * its email domain is disposable-adjacent
483	     * ({@link DisposableDomains#isDisposableAdjacent(String)}), or its city was over its soft
484	     * capacity at creation ({@link #isCapacityWarning()}) — otherwise {@code false}.
485	     */
486	    @Transient
487	    public boolean isRiskFlag() {
488	        return this.possibleDuplicate
489	            || DisposableDomains.isDisposableAdjacent(this.email)
490	            || this.capacityWarning;
491	    }
492	
493	    /**
494	     * Whether this owner has been soft-deleted: DELETE /api/owners/{id} sets this flag rather than
495	     * removing the row, so the owner is retained and still readable but is ignored by the create
496	     * endpoint's duplicate and identity checks. A newly created owner is not deleted.
497	     */
498	    public boolean isDeleted() {
499	        return this.deleted;
500	    }
501	
502	    public void setDeleted(boolean deleted) {
503	        this.deleted = deleted;
504	    }
505	
506	    /**
507	     * The {@code Idempotency-Key} the owner was first created under, or {@code null} when the create
508	     * carried no such header. When a create repeats with an already-seen key, the originally created
509	     * owner is returned instead of a duplicate being created, so the key is retained to recognise the
510	     * repeat.
511	     */
512	    public String getIdempotencyKey() {
513	        return this.idempotencyKey;
514	    }
515	
516	    public void setIdempotencyKey(String idempotencyKey) {
517	        this.idempotencyKey = idempotencyKey;
518	    }
519	
520	    protected Set<Pet> getPetsInternal() {
521	        if (this.pets == null) {
522	            this.pets = new HashSet<>();
523	        }
524	        return this.pets;
525	    }
526	
527	    protected void setPetsInternal(Set<Pet> pets) {
528	        this.pets = pets;
529	    }
530	
531	    public List<Pet> getPets() {
532	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
533	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
534	        return Collections.unmodifiableList(sortedPets);
535	    }
536	
537	    public void setPets(List<Pet> pets) {
538	        this.pets = new HashSet<>(pets);
539	    }
540	
541	    public void addPet(Pet pet) {
542	        getPetsInternal().add(pet);
543	        pet.setOwner(this);
544	    }
545	
546	    /**
547	     * Return the Pet with the given name, or null if none found for this Owner.
548	     *
549	     * @param name to test
550	     * @return true if pet name is already in use
551	     */
552	    public Pet getPet(String name) {
553	        return getPet(name, false);
554	    }
555	
556	    /**
557	     * Return the Pet with the given name, or null if none found for this Owner.
558	     *
559	     * @param name to test
560	     * @return true if pet name is already in use
561	     */
562	    public Pet getPet(String name, boolean ignoreNew) {
563	        name = name.toLowerCase();
564	        for (Pet pet : getPetsInternal()) {
565	            if (!ignoreNew || !pet.isNew()) {
566	                String compName = pet.getName();
567	                compName = compName.toLowerCase();
568	                if (compName.equals(name)) {
569	                    return pet;
570	                }
571	            }
572	        }
573	        return null;
574	    }
575	
576	    public Pet getPet(Integer petId) {
577	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
578	    }
579	
580	    @Override
581	    public String toString() {
582	        return new ToStringCreator(this)
583	
584	            .append("id", this.getId())
585	            .append("new", this.isNew())
586	            .append("lastName", this.getLastName())
587	            .append("firstName", this.getFirstName())
588	            .append("address", this.address)
589	            .append("city", this.city)
590	            .append("telephone", this.telephone)
591	            .toString();
592	    }
593	}
