20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "selfLink", expression = "java(toSelfLink(owner))")
27	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
28	    @Mapping(target = "salutation", expression = "java(owner.getSalutation())")
29	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
30	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
31	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
34	    @Mapping(target = "ownerSegment", expression = "java(toOwnerSegment(owner))")
35	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
36	    @Mapping(target = "fiscalYear", expression = "java(owner.getFiscalYear())")
37	    @Mapping(target = "riskFlag", expression = "java(owner.isRiskFlag())")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derive the owner's read-only {@code selfLink}: the canonical API path of this owner,
42	     * {@code '/api/owners/<id>'}, built from the owner's assigned id. Returns {@code null}
43	     * when the owner has no id yet, so the field is omitted from the response.
44	     */
45	    default String toSelfLink(Owner owner) {
46	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * Derive the owner's read-only {@code telephoneDisplay}: the stored E.164 {@code telephone}
51	     * formatted for humans (country code, a space, then the national digits grouped in threes),
52	     * e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}. Returns {@code null} when the
53	     * owner has no telephone, so the field is omitted from the response.
54	     */
55	    default String toTelephoneDisplay(Owner owner) {
56	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
57	    }
58	
59	    /**
60	     * Derive the owner's read-only {@code ageBand} enum from its {@code birthDate}, computed against
61	     * the owner's {@code registrationDate} (see {@link Owner#getAgeBand()}). Returns {@code null}
62	     * when the owner has no {@code birthDate}, so the field is omitted from the response.
63	     */
64	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
65	        String ageBand = owner.getAgeBand();
66	        return ageBand == null ? null : OwnerDto.AgeBandEnum.fromValue(ageBand);
67	    }
68	
69	    /**
70	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
71	     * read-only {@code displayName} field returned on the Owner DTO.
72	     */
73	    default String toDisplayName(Owner owner) {
74	        return owner.getLastName() + ", " + owner.getFirstName();
75	    }
76	
77	    /**
78	     * Build the owner's initials as the upper-cased first letters of firstName and
79	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
80	     * read-only {@code initials} field returned on the Owner DTO.
81	     */
82	    default String toInitials(Owner owner) {
83	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
84	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
85	    }
86	
87	    /**
88	     * Derive the owner's read-only {@code locality}: the REGION segment of the owner's
89	     * {@code memberId} ({@code '<REGION><FY><HASH8><CHK>'}), the unified member id the owner is
90	     * assigned at creation. Falls back to resolving the region directly from the owner's postcode
91	     * range first ({@code NSW 2000-2099, VIC 3000-3099, QLD 4000-4099}), then the canonical region
92	     * of the owner's city ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), else {@code 'UNKNOWN'},
93	     * when the owner has no {@code memberId} yet. Sourcing it from the identity keeps the owner's
94	     * reported locality and its {@code memberId} region in lock-step.
95	     */
96	    default String toLocality(Owner owner) {
97	        String region = Owner.regionSegment(owner.getMemberId());
98	        if (region != null) {
99	            return region;
100	        }
101	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity());
102	    }
103	
104	    /**
105	     * Derive the owner's read-only {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
106	     * {@code PREMIUM} when the owner's {@code membershipLevel} is 3 or more, otherwise
107	     * {@code STANDARD}. AREA is {@code METRO} when the owner's {@code locality} resolves to a known
108	     * region, otherwise {@code REGIONAL}. The known-region test leans on {@link #toLocality(Owner)},
109	     * which collapses every city/postcode not in the central region tables to the {@code 'UNKNOWN'}
110	     * sentinel, so a region added or renamed in those tables is reflected here in lock-step.
111	     */
112	    default OwnerDto.OwnerSegmentEnum toOwnerSegment(Owner owner) {
113	        String tier = owner.getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
114	        String area = "UNKNOWN".equals(toLocality(owner)) ? "REGIONAL" : "METRO";
115	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
116	    }
117	
118	    /**
119	     * Derive the owner's read-only {@code timezone}: the IANA timezone name for the owner's
120	     * locality/region, looked up from the fixed region-to-timezone table ({@code NSW->Australia/Sydney,
121	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane}). The region is the same value reported as the
122	     * owner's {@code locality} (see {@link #toLocality(Owner)}), so timezone and locality stay in
123	     * lock-step. Returns {@code null} when the region has no mapped timezone, so the field is omitted
124	     * from the response.
125	     */
126	    default String toTimezone(Owner owner) {
